-- SQL Quest practice dataset "company": Acme Corp
-- Generated by scripts/gen-datasets.mjs (deterministic) - edit the generator, not this file.

CREATE TABLE departments (
    dept_id  integer PRIMARY KEY,
    name     text NOT NULL UNIQUE,
    location text NOT NULL,
    budget   numeric(12,2) NOT NULL
);

CREATE TABLE employees (
    emp_id          integer PRIMARY KEY,
    first_name      text NOT NULL,
    last_name       text NOT NULL,
    email           text NOT NULL UNIQUE,
    dept_id         integer REFERENCES departments (dept_id),
    manager_id      integer REFERENCES employees (emp_id),
    job_title       text NOT NULL,
    hire_date       date NOT NULL,
    salary          numeric(10,2) NOT NULL,
    employment_type text NOT NULL,
    city            text NOT NULL,
    terminated_on   date
);

CREATE TABLE salary_history (
    emp_id         integer NOT NULL REFERENCES employees (emp_id),
    effective_date date NOT NULL,
    salary         numeric(10,2) NOT NULL,
    PRIMARY KEY (emp_id, effective_date)
);

CREATE TABLE projects (
    project_id integer PRIMARY KEY,
    name       text NOT NULL,
    dept_id    integer NOT NULL REFERENCES departments (dept_id),
    start_date date NOT NULL,
    end_date   date,
    budget     numeric(12,2) NOT NULL,
    status     text NOT NULL
);

CREATE TABLE project_assignments (
    emp_id         integer NOT NULL REFERENCES employees (emp_id),
    project_id     integer NOT NULL REFERENCES projects (project_id),
    role           text NOT NULL,
    hours_per_week integer NOT NULL,
    assigned_on    date NOT NULL,
    PRIMARY KEY (emp_id, project_id)
);






ANALYZE;
